changeSet.sql:
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT (SELECT f.id FROM pep_function f JOIN pep_category c ON c.id = f.category_id WHERE c.country_iso = 'DE' AND f.label = 'Allemand exerçant une autre fonction PEP dans une institution de l''UE'), p.id, 'COMPLETE', FALSE, 'Allemands membres de la Cour de justice et du Tribunal, de la Cour des comptes europeenne, du directoire et du conseil de surveillance prudentielle de la BCE, et secretaire general du Conseil (pages officielles). Commissaires et deputes europeens : de_pep_eu_commission et de_pep_europarl.', 'Nationalite deduite de la source (pays indique, naissance, autorite nationale) ; les CV de la BCE ne donnent plus le lieu de naissance (liste knownNationals). Page du Secretariat general du Conseil fermee aux robots (HTTP 403). Agences et autres organes de l''UE non lus.' FROM parser p WHERE p.dataset_name = 'de_pep_eu_institutions';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT (SELECT f.id FROM pep_function f JOIN pep_category c ON c.id = f.category_id WHERE c.country_iso = 'DE' AND f.label = 'Attaché de défense'), p.id, 'PARTIAL', FALSE, 'Attaches de defense allemands nommes dans les listes diplomatiques officielles de la Suede, du Royaume-Uni, de l''Islande, de la Macedoine du Nord, de l''Estonie, du Danemark, de la Thailande et de Singapour.', 'L''Allemagne ne publie pas la liste de ses attaches de defense (environ 90 postes) ; seuls les pays d''accueil dont la liste est publique et lisible sont couverts. Listes fermees aux robots : Irlande, Albanie, Azerbaidjan ; liste de la Georgie en deux colonnes non lue.' FROM parser p WHERE p.dataset_name = 'de_pep_defence_attaches';
UPDATE pep_function f JOIN pep_category c ON c.id = f.category_id SET f.expected_holders = 90 WHERE c.country_iso = 'DE' AND f.label = 'Attaché de défense' AND f.expected_holders IS NULL;
